import React, { useState } from "react";

export default function TextInputDisplay() {
  const [text, setText] = useState("");
  const [fileContent, setFileContent] = useState("");
  const [file, setFile] = useState(null);
  const [output, setOutput] = useState([]);
  const [acciones, setAcciones] = useState([]); // NUEVO
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleTextChange = (e) => {
    setText(e.target.value);
    if (e.target.value) {
      setFile(null);
      setFileContent("");
    }
  };

  const handleFileChange = async (event) => {
    if (event.target.files.length > 0) {
      const selectedFile = event.target.files[0];
      const reader = new FileReader();
      reader.onload = (e) => {
        const content = e.target.result;
        setFileContent(content);
        setText("");
      };
      reader.readAsText(selectedFile);
      setFile(selectedFile);
    }
  };

  const formatToken = (token) => {
    const typeMap = {
      "NUMERO": "num",
      "IDENTIFICADOR": "id",
      "OPERADOR": "op",
      "OPERADOR_COMPARACION": "op_comp",
      "OPERADOR_LOGICO": "op_log",
      "AGRUPADOR": "agrup",
      "PUNTO_Y_COMA": "ptcoma",
      "TIPO_DATO": "tipo",
      "PALABRA_RESERVADA": "palres",
      "FUNCION_RESERVADA": "func",
      "BOOLEANO": "bool",
      "CHAR": "char",
      "LITERAL": "lit",
      "ERROR": "error"
    };

    const tipo = token.tipo || 'error';
    const valor = token.valor || '?';

    return `<${typeMap[tipo] || tipo.toLowerCase()},${valor}>`;
  };

  const handleAnalyze = async () => {
    const contentToAnalyze = fileContent || text;

    if (!contentToAnalyze.trim()) {
      setError("Por favor, ingresa un código fuente o carga un archivo.");
      return;
    }

    setLoading(true);
    setError("");
    setOutput([]);
    setAcciones([]); // NUEVO

    try {
      const response = await fetch("http://localhost:8081/api/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ code: contentToAnalyze }),
      });

      const data = await response.json();

      if (!response.ok) {
        if (data.errores && data.errores.length > 0) {
          const erroresStr = data.errores.map(e =>
            `Línea ${e.linea}, Columna ${e.columna}: ${e.mensaje}`
          ).join('\n');
          setError(erroresStr);
        } else {
          setError(data.message || "Error al analizar el código");
        }
        setOutput([]);
        setAcciones([]);
        return;
      }

      setOutput(data.tokens || []);
      setAcciones(data.acciones || []); // NUEVO
    } catch (err) {
      setError(`Error de conexión: ${err.message}`);
      setOutput([]);
      setAcciones([]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        minHeight: "100vh",
        backgroundColor: "#FFFFFF",
        padding: "20px",
      }}
    >
      <h1 style={{ fontSize: "20px", fontWeight: "bold", marginBottom: "8px" }}>
        Ingresar código fuente
      </h1>
      <input
        type="text"
        value={text}
        onChange={handleTextChange}
        style={{
          border: "1px solid #ccc",
          padding: "20px",
          borderRadius: "8px",
          width: "300px",
          fontSize: "10px",
          marginBottom: "12px",
        }}
        placeholder="Escribe aquí el código fuente"
        disabled={file !== null}
      />

      <h1 style={{ fontSize: "20px", fontWeight: "bold", marginBottom: "8px" }}>
        O carga el archivo del mismo aquí
      </h1>
      <input
        type="file"
        onChange={handleFileChange}
        style={{ marginBottom: "15px" }}
        disabled={text !== ""}
      />

      <div
        style={{
          marginTop: "25px",
          padding: "10px",
          backgroundColor: "rgb(182, 215, 228)",
          boxShadow: "0px 0px 8px rgba(0,0,0,0.1)",
          borderRadius: "5px",
          width: "150px",
          textAlign: "center",
          cursor: "pointer",
        }}
        onMouseEnter={(e) =>
          (e.target.style.backgroundColor = "rgb(0, 183, 255)")
        }
        onMouseLeave={(e) =>
          (e.target.style.backgroundColor = "rgb(182, 215, 228)")
        }
        onClick={handleAnalyze}
      >
        <p style={{ fontSize: "12px", fontWeight: "bold" }}>
          {loading ? "Analizando..." : "Pulsa aquí para utilizar el analizador Léxico"}
        </p>
      </div>

      {error && (
        <div style={{
          color: "red",
          marginTop: "10px",
          backgroundColor: "#ffeeee",
          padding: "10px",
          border: "1px solid #ffcccc",
          borderRadius: "4px",
          whiteSpace: "pre-wrap"
        }}>
          <strong>Errores encontrados:</strong>
          <div style={{ marginTop: "5px" }}>{error}</div>
        </div>
      )}

      <div
        style={{
          marginTop: "30px",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          gap: "500px",
        }}
      >
        <h1>Entrada</h1>
        <h1>Salida</h1>
      </div>

      <div
        style={{
          marginTop: "20px",
          display: "flex",
          justifyContent: "space-between",
          width: "80%",
          padding: "0 50px",
        }}
      >
        <div
          style={{
            border: "1px solid #ccc",
            padding: "10px",
            width: "40%",
            minHeight: "200px",
            backgroundColor: "#f7f7f7",
          }}
        >
          <pre>{fileContent || text}</pre>
        </div>

        <div
          style={{
            border: "1px solid #ccc",
            padding: "10px",
            width: "40%",
            minHeight: "200px",
            backgroundColor: "#f7f7f7",
          }}
        >
          {output.length > 0 ? (
            <div>
              <div style={{
                fontFamily: "monospace",
                backgroundColor: "#fff",
                padding: "10px",
                marginBottom: "20px",
                border: "1px solid #ddd",
                borderRadius: "4px"
              }}>
                {output.map((token, index) => (
                  <span key={index}>
                    {formatToken(token)}{' '}
                  </span>
                ))}
              </div>

              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr>
                    <th style={{ border: "1px solid #ccc", padding: "8px" }}>Tipo</th>
                    <th style={{ border: "1px solid #ccc", padding: "8px" }}>Valor</th>
                    <th style={{ border: "1px solid #ccc", padding: "8px" }}>Línea</th>
                    <th style={{ border: "1px solid #ccc", padding: "8px" }}>Columna</th>
                  </tr>
                </thead>
                <tbody>
                  {output.map((token, index) => (
                    <tr key={index}>
                      <td style={{ border: "1px solid #ccc", padding: "8px" }}>{token.tipo}</td>
                      <td style={{ border: "1px solid #ccc", padding: "8px" }}>{token.valor}</td>
                      <td style={{ border: "1px solid #ccc", padding: "8px" }}>{token.linea}</td>
                      <td style={{ border: "1px solid #ccc", padding: "8px" }}>{token.columna}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p>No hay tokens generados.</p>
          )}

          {/* NUEVA SECCIÓN: ACCIONES */}
          {acciones.length > 0 && (
            <div className="mt-6">
              <h2 className="font-semibold text-lg mb-2">Acciones:</h2>
              <ul className="list-disc pl-5 text-green-700">
                {acciones.map((accion, index) => (
                  <li key={index}>{accion}</li>
                ))}
              </ul>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
